                group_shift, form.has_offset ? 1 : 0, threads_per_row);
            break;
        case 4:
            s_gemv_split_kernel<4><<<grid, threads_per_row, smem, stream>>>(
                x, codes, scales, offset, y, n_in, n_out, form.code_bias, cb, form.group_elems,
                group_shift, form.has_offset ? 1 : 0, threads_per_row);
